SS2_CIV = [
 ("HIV/AIDS & Stigma",
  [("Introduction", ["HIV (Human Immunodeficiency Virus) attacks the body's immune system; AIDS (Acquired Immune Deficiency Syndrome) is the advanced stage of the infection, when the immune system is badly damaged. It is a major public health challenge requiring knowledge, compassion and prevention."]),
   ("Transmission", ["The virus spreads through: unprotected sexual contact with an infected person; infected blood (transfusion, unsterilised needles and blades); and from mother to child (during pregnancy, birth or breastfeeding). It is NOT spread by hugging, shaking hands, sharing food, mosquito bites, toilet seats or swimming pools."]),
   ("Prevention and treatment", ["Abstinence, faithfulness, the correct use of condoms; only screened blood; sterilised needles and blades; prevention of mother-to-child transmission (PMTCT); testing and counselling; and antiretroviral therapy (ART) which controls the virus and lets people live long, healthy lives."]),
   ("Stigma and discrimination", ["Stigma is the negative attitude society holds about people living with HIV; discrimination is unfair treatment. Stigma drives people away from testing, hides the epidemic and breaks families. The right response is education, compassion, confidentiality and the protection of the rights of people living with HIV (the Anti-Stigma law and the HIV and AIDS (Anti-Discrimination) Act)."]),
   ("Class evaluation", ["Define HIV and AIDS.", "State two ways HIV is and is not transmitted.", "Mention two methods of prevention.", "Why is stigma harmful to the fight against HIV/AIDS?"])]),
 ("Human Trafficking",
  [("Introduction", ["Human trafficking is the recruitment, transportation, harbouring or receipt of persons by means of force, deceit or coercion, for exploitation — forced labour, sexual exploitation, begging, domestic servitude, organ removal or child soldiering. It is modern slavery and a crime."]),
   ("Forms and causes", ["Forms: trafficking for prostitution (especially of girls), child labour, domestic servitude, street begging, and the use of children for ritual purposes. Causes: poverty and unemployment; ignorance and deception by traffickers ('good jobs abroad'); weak family bonds; broken homes; greed; poor enforcement of laws; and large, unregulated migration."]),
   ("Consequences", ["Victims suffer physical abuse, diseases (including HIV), psychological trauma, loss of education and identity, social rejection and death. The nation loses young talent; the country's image abroad is damaged."]),
   ("Prevention and response", ["Public enlightenment and education; poverty alleviation and youth empowerment; stricter law enforcement (the Trafficking in Persons (Prohibition) Enforcement and Administration Act 2015 and NAPTIP — the National Agency for the Prohibition of Trafficking in Persons); the protection, rehabilitation and reintegration of victims; border surveillance; and the registration and regulation of employment agencies."]),
   ("Class evaluation", ["Define human trafficking.", "State three causes of trafficking in Nigeria.", "Mention four consequences of trafficking.", "What is the role of NAPTIP?"])]),
 ("Gender & Equality",
  [("Introduction", ["Gender refers to the roles, behaviours and attributes that society assigns to men and women; sex is the biological difference. Gender equality means that men and women enjoy the same rights, opportunities and dignity."]),
   ("Issues of inequality in Nigeria", ["Girls are denied education in some communities; women face discrimination in inheritance and property rights; unequal access to jobs, credit and leadership; early/child marriage; gender-based violence (domestic abuse, rape, female genital mutilation); the under-representation of women in politics and public office; and the unequal burden of unpaid housework."]),
   ("The case for equality", ["Equal rights are human rights — guaranteed by the constitution (freedom from discrimination) and international instruments (CEDAW, the Beijing Platform). Equality is also economic sense: educated and employed women raise family incomes, child health and national development."]),
   ("What can be done", ["Girl-child education campaigns; laws against violence and harmful practices (the Violence Against Persons (Prohibition) Act 2015); affirmative action (quotas for women in politics and boards); empowerment programmes and credit for women; the education of boys and girls in shared responsibility; and the media projecting women as equals."]),
   ("Class evaluation", ["Differentiate between sex and gender.", "State three forms of gender inequality in Nigeria.", "Mention two laws protecting women.", "How can girls' education be promoted in your community?"])]),
 ("Social Justice & Inclusiveness",
  [("Introduction", ["Social justice is the fair distribution of benefits and burdens in society: equal rights, equal opportunity and fairness for all — regardless of income, gender, ethnicity, religion or disability. Inclusiveness means bringing all groups into the mainstream of national life."]),
   ("Dimensions", ["<b>Economic justice</b> — fair wages, equal opportunity, safety nets (the poverty alleviation programmes, conditional cash transfers, minimum wage). <b>Political justice</b> — the right to vote and be voted for, fair representation (the Federal Character principle, the Not-Too-Young-To-Run Act). <b>Legal justice</b> — equal treatment before the law, free legal aid. <b>Social justice</b> — access to education, health and housing for all; the care of the elderly, the disabled and vulnerable children."]),
   ("Barriers in Nigeria", ["Poverty and inequality; corruption that diverts public resources; discrimination against women, persons with disabilities (the Discrimination Against Persons with Disabilities (Prohibition) Act 2019) and ethnic minorities; regional imbalance; and weak institutions."]),
   ("Promoting inclusiveness", ["Good governance and the rule of law; social investment programmes (N-Power, conditional transfers); free and compulsory basic education; universal health care (NHIA); infrastructure in the rural areas; affirmative action; and civic education on the dignity of every person."]),
   ("Class evaluation", ["Define social justice.", "State three dimensions of social justice.", "Mention two barriers to inclusiveness in Nigeria.", "What is the Federal Character principle and why was it introduced?"])]),
 ("Culture, Values & Social Norms",
  [("Introduction", ["Culture is the total way of life of a people — their language, religion, food, dress, arts, music and institutions, handed down from generation to generation. Values are the standards a people hold dear; social norms are the accepted rules of behaviour."]),
   ("Elements of Nigerian culture", ["Languages (over 250); festivals (New Yam, Argungu, Eyo, Durbar); dress; food; music and dance; arts and crafts; religion; greetings and the extended family system; and folklore. Cultural diversity is Nigeria's glory — unity in diversity is the national motto's spirit."]),
   ("Positive and negative norms", ["Positive: hospitality, respect for elders, honesty, hardwork, community spirit, religious tolerance. Negative: tribalism, child marriage, gender discrimination, extravagant ceremonies (wasteful funerals and weddings), bribery and the celebration of ill-gotten wealth. Value re-orientation campaigns (the National Re-orientation Agency) seek to revive good values."]),
   ("Culture in a global world", ["Globalisation and the mass media spread foreign culture — some good (science, human rights), some harmful (drug culture, indecent dressing, erosion of languages). The task: keep the good of our culture while taking the best from others."]),
   ("Class evaluation", ["Define culture and give its elements.", "Mention three positive and three negative Nigerian norms.", "How does globalisation affect Nigerian culture?", "Why is unity in diversity important for Nigeria?"])]),
 ("National Consciousness & Patriotism (Revision)",
  [("Introduction", ["National consciousness is the awareness of belonging to one nation — Nigeria — and of the duties that follow; patriotism is the love of that nation and the willingness to serve it. This week revises the term's civic themes and turns them into action."]),
   ("The national identity", ["The symbols of nationhood: the flag (green, white, green — agriculture, peace and unity), the coat of arms (the eagle, the horses, the shield, the 'Unity and Faith' motto), the National Anthem ('Arise, O Compatriots'), the pledge, the currency, the passport, and the national holidays. Loyalty to these symbols is the first act of patriotism."]),
   ("What divides and what unites", ["Dividers: ethnic and religious prejudice, sectionalism, corruption, poverty and inequality; unifiers: the constitution, the national symbols, the armed forces, the national grid institutions (NNPC, NAFDAC, NIDCOM), shared festivals, food and music, and the common struggles of citizenship."]),
   ("The patriotic citizen", ["Pays taxes and rates; obeys the law; protects public property; votes and is voted for; defends the country's image (including online); participates in the community (clean-up, blood donation, the NYSC); rejects cultism, drug abuse and examination malpractice; and serves with excellence wherever he or she works."]),
   ("Class evaluation", ["Define patriotism.", "What do the green and white of the flag represent?", "State the national motto.", "List four duties of a patriotic citizen.", "Mention two things that unite Nigerians."])]),
]

SS2_FOOD = [
 ("Egg, Meat & Fish Cookery",
  [("Introduction", ["Eggs, meat and fish are protein foods — the body's builders. Their cookery requires care to keep them tender, digestible, safe and nutritious."]),
   ("Egg cookery", ["Eggs coagulate (set) when heated; overcooking makes them tough, rubbery and discoloured. Methods: boiling (soft or hard — hard eggs 8–10 minutes), frying, poaching, scrambling, omelettes; eggs as binders, thickeners and emulsifiers (mayonnaise) and in cakes. To test freshness: a fresh egg sinks in water; a stale one floats (the air space enlarges). Use in dishes: custard, egg sauce, meat pies."]),
   ("Meat cookery", ["Cut, type and age determine cooking: tender cuts (fillet, steak) for frying/grilling; less tender cuts (shin, neck) for stewing and braising (which soften the connective tissue). Methods: roasting, grilling, frying, stewing, boiling, braising; good hygiene, thorough cooking (to kill bacteria), and resting after cooking. Avoid re-freezing thawed meat."]),
   ("Fish cookery", ["Fish is tender and cooks quickly; it may be steamed, boiled, fried, grilled, baked or smoked. Whole fish is judged fresh by bright eyes, red gills, firm flesh and a fresh smell. Serving size and the bones matter for children. Fish is preserved by smoking, salting, drying, freezing and canning."]),
   ("Class evaluation", ["State two effects of overcooking eggs.", "Why are some cuts stewed and others grilled?", "How do you test the freshness of fish?", "Name three methods of preserving fish."])]),
 ("Milk & Dairy Products",
  [("Introduction", ["Milk is an almost complete food — protein, fat, carbohydrate, calcium, vitamins A and D and water. Dairy products are foods made from milk: fresh milk, evaporated and powdered milk, yoghurt, cheese, butter, ice cream and custard."]),
   ("Types and properties", ["<b>Fresh (liquid) milk</b> — perishable, pasteurised (heated to 72 °C for 15 s) to kill germs; <b>evaporated and condensed milk</b> — heat-treated, long shelf life; <b>powdered (dried) milk</b> — water removed, easy to store; <b>yoghurt</b> — fermented by bacteria (Lactobacillus); <b>cheese</b> — milk protein (casein) coagulated with rennet, then pressed and ripened; <b>butter</b> — churned cream. Milk boils over easily and scorches; use a heavy pan and stir; keep dairy refrigerated."]),
   ("Uses in cookery", ["Milk and cream in sauces, custards, cakes, bread (the Tang method), tea, coffee, and ice cream; butter for fat, flavour and pastry; cheese for toppings, sauces and snacks; yoghurt for dressings and smoothies."]),
   ("Class evaluation", ["Name the nutrients in milk.", "Why is milk pasteurised?", "How is cheese made?", "State two rules for storing dairy products."])]),
 ("Pulses, Nuts & Vegetables",
  [("Introduction", ["Pulses (beans, soya, cowpea, lentils), nuts (groundnut, cashew, melon seeds) and vegetables are the plant proteins and protective foods of the Nigerian diet."]),
   ("Pulses", ["Cheap sources of protein, B vitamins, minerals and fibre: cowpea (beans), soya bean (the complete protein), groundnut, pigeon pea, bambara. Cook by soaking, then boiling or pressure cooking — pulses must be boiled thoroughly to destroy toxins and aid digestion; soaking shortens cooking time. Uses: bean cakes (akara), moin-moin, bean porridge, groundnut soup and butter."]),
   ("Nuts and seeds", ["Groundnut (oil, butter, roasted), cashew, melon seeds (egusi), sesame (beniseed), coconut. They give oils, proteins and minerals; store cool and dry (they go rancid); raw groundnuts may carry aflatoxin — buy good quality."]),
   ("Vegetables", ["Leafy (ugu, waterleaf, spinach, cabbage), fruit (tomato, pepper, okra), root (carrot, onion) and pulse vegetables. They supply vitamins, minerals and fibre. Cook quickly in little water to retain nutrients; use the water for soup; wash before cutting."]),
   ("Class evaluation", ["Define pulses and give three examples.", "Why must beans be boiled thoroughly?", "State two methods of preparing groundnuts.", "What nutrients do vegetables supply?"])]),
 ("Baking: Cakes & Pastry",
  [("Introduction", ["Baking is cooking by dry heat in an oven. Cakes and pastries are flour mixtures raised by chemical leavening (baking powder) or by the air beaten in (sponges) — and by fat and sugar creaming. Accurate weighing and oven control give good results."]),
   ("Cake methods", ["<b>Creaming</b> — beat fat and sugar, add eggs, fold in flour (Victoria/plain cake); <b>melting</b> — melt fat and sugar, add the rest (fruit cakes); <b>rubbing-in</b> — rub fat into flour (scones, shortcrust); <b>whisking</b> — whisk eggs and sugar, fold in flour (sponges). Ingredients: flour (soft for cakes), fat, sugar, eggs, milk, baking powder and flavourings."]),
   ("Pastry", ["Shortcrust (flour:fat 2:1, rubbed in, little cold water — for pies and tarts); puff pastry (layers of fat — flaky); choux (for eclairs); flaky. Rules: keep everything cool, handle lightly, roll evenly, and bake hot (200 °C) so the pastry rises before setting."]),
   ("Common faults", ["Sunken cakes — too little heat or too much raising agent; heavy cakes — over-mixed or the fat too soft; tough pastry — too much liquid or over-handling; burnt tops — too hot an oven."]),
   ("Class evaluation", ["Name four ingredients of a plain cake.", "Differentiate the creaming and rubbing-in methods.", "State the ratio of flour to fat in shortcrust pastry.", "Why is pastry handled lightly?"])]),
 ("Bread Making & Yeast Baking",
  [("Introduction", ["Bread is made from flour (strong wheat flour), yeast, water, salt and sometimes sugar and fat. Yeast ferments the sugars to carbon dioxide, which raises the dough — the process of fermentation and proving."]),
   ("The process", ["1. Mixing: combine the ingredients into a dough. 2. Kneading: work the dough to develop the gluten (the elastic network that holds the gas). 3. Proving (first rise): leave in a warm place until doubled (about 1 hour). 4. Knock back and shape. 5. Prove again briefly. 6. Bake at about 220 °C, testing with a skewer or tap the base (a hollow sound means it is done). 7. Cool on a rack; brush the crust with butter for a soft finish."]),
   ("Ingredients and their jobs", ["Flour — the structure (gluten); yeast — the raising agent (warmth and sugar activate it); water — hydrates and brings the gluten together; salt — flavour and control of the yeast; sugar — food for the yeast; fat — softness and keeping quality."]),
   ("Faults", ["A heavy, dense loaf — the yeast was dead, too cold, or kneading was poor; a sour taste — over-proving; a cracked or split top — the oven too hot or over-proofed; a pale crust — too low heat."]),
   ("Class evaluation", ["Name the ingredients of bread and the job of each.", "What is gluten and why is kneading important?", "State the steps of bread making in order.", "Why must the dough be left in a warm place?"])]),
 ("Dough & Batter Cookery (Pancakes, Puff-Puff & Chin-Chin)",
  [("Introduction", ["Doughs and batters are mixtures of flour and liquid, leavened by air, steam or raising agents; the difference is consistency — a dough is stiff enough to handle, a batter pours. Nigerian favourites — puff-puff, chin-chin, pancakes — are all products of these mixtures."]),
   ("The mixtures", ["<b>Batters</b> — thin (crêpes, Yorkshire pudding) or thick (pancakes, waffles, fritters); <b>doughs</b> — soft (puff-puff, doughnuts) or stiff (chin-chin, biscuits, pastries). Ingredients: flour (the structure), liquid (water, milk), fat, egg, sugar, salt (with yeast — it controls fermentation) and the leavening agent."]),
   ("Raising agents", ["<b>Biological</b> — yeast (the fermentation of sugar → carbon dioxide: puff-puff, doughnuts); <b>chemical</b> — baking powder and bicarbonate of soda (acid + alkali + heat → gas); <b>physical</b> — the air beaten in (egg foam, whisking) and steam (choux pastry, pikelets)."]),
   ("The methods", ["<b>Puff-puff</b> — mix flour, yeast, sugar, salt and water; leave to rise, covered; fry spoonfuls in hot oil (180 °C) until golden. <b>Chin-chin</b> — a stiff dough with margarine, milk and nutmeg; roll, cut into strips or squares, and deep-fry. <b>Pancakes</b> — a thin batter (flour, egg, milk, salt); pour into a greased pan, fry both sides, and serve with honey or sugar. Rules: sieve the flour; mix evenly; keep the frying temperature steady; drain on absorbent paper."]),
   ("Class evaluation", ["Differentiate a dough from a batter.", "Name the three types of raising agents with one example each.", "Why is sugar added when using yeast?", "What oil temperature is best for frying?", "List four rules of successful deep-frying."])]),
]

SS2_GOV = [
 ("Local Government Administration",
  [("Introduction", ["Local government is the third tier of government in Nigeria — the grass-root level closest to the people. The 1976 local government reforms standardised it: 774 local government areas today, each with an elected chairman and councillors."]),
   ("Functions of local government", ["Collecting rates, licences and fees; constructing and maintaining roads, drains, parks and markets; primary education (now partly federal/state); primary health care and clinics; sanitation and waste disposal; registration of births, deaths and marriages; agricultural extension support; and providing community development."]),
   ("Structure", ["The chairman (executive head), the legislative council (the councillors), the local government secretariat (departments: administration, finance, works, health, education, agriculture), and traditional rulers who advise. Revenue comes from statutory allocations (from the federation account), internally generated revenue, and the state's share."]),
   ("Problems", ["Inadequate finance and dependence on allocations; corruption and mismanagement; poor staff training; political interference by the state; the denial of autonomy; and the inability to provide services. Reforms seek financial autonomy (the Supreme Court ruling of 2024 on direct allocations)."]),
   ("Class evaluation", ["Define local government.", "List five functions of local government.", "State the sources of local government revenue.", "Mention three problems facing local governments."])]),
 ("Nigerian Colonial History",
  [("Introduction", ["Colonial rule in Nigeria began with the British annexation of Lagos in 1861 and the establishment of the protectorates, and ended with independence in 1960. It changed Nigeria's political, economic and social life profoundly."]),
   ("Stages of colonisation", ["The missionaries and traders came first (the Royal Niger Company); the Berlin Conference (1884–85) formalised the partition of Africa; the amalgamation of the Northern and Southern protectorates took place in 1914 by Lord Frederick Lugard. Britain ruled through indirect rule — governing through the traditional chiefs and emirs."]),
   ("Political legacy", ["The colonial state created Nigeria's boundaries (arbitrarily drawn), the central bureaucracy, the judiciary, and a new educated elite; but it also divided the country into regions (North, East, West), promoted ethnic separateness through indirect rule, and left a centralised, expensive administration. The colonial economy was built for export (palm oil, cocoa, groundnut, tin) and the importation of manufactures — a pattern that persists."]),
   ("Class evaluation", ["When was Nigeria amalgamated and by whom?", "What is indirect rule?", "State two political legacies of colonial rule.", "How did the colonial economy shape Nigerian trade?"])]),
 ("Nigerian Nationalism",
  [("Introduction", ["Nationalism is the struggle for self-government — the movement for independence. Nigerian nationalism grew from the educated elite, the press, the trade unions, the youth movements and the political parties."]),
   ("The movement and its leaders", ["Early stirrings: the Aba women's riot (1929) against taxation; the Nigerian Youth Movement (1936); the press (Herbert Macaulay, Nnamdi Azikiwe — 'Zik of Africa'); the trade unions (Michael Imoudu); and the pan-African ideas of the era. Leading nationalists: Herbert Macaulay, Nnamdi Azikiwe, Obafemi Awolowo, Ahmadu Bello, J.S. Tarka, Anthony Enahoro, Fummilayo Ransome-Kuti, Tafawa Balewa."]),
   ("Factors that aided nationalism", ["Western education and the educated elite; the Second World War (returning soldiers and the Atlantic Charter); the exploitation of the colonial economy; the growth of the press and radio; pan-Africanism and the independence of Asian countries (India, Ghana in 1957); and the formation of political parties — the NCNC (1944), the Action Group (1951) and the NPC (1951)."]),
   ("Class evaluation", ["Define nationalism.", "Name four Nigerian nationalists.", "Mention three factors that aided nationalism.", "Which constitution gave Nigeria internal self-government in the regions? (The 1954 Lyttleton Constitution.)"])]),
 ("Independence & The First Republic",
  [("Introduction", ["Nigeria became independent on 1 October 1960 and a republic in 1963. The First Republic (1960–1966) was marred by regional tensions and ended in the first military coup in January 1966."]),
   ("The road to independence", ["Self-government came in 1957 (the North in 1959); the 1960 independence was achieved through constitutional conferences (London 1957, 1958); Sir Abubakar Tafawa Balewa became the first Prime Minister; Dr Nnamdi Azikiwe the first Governor-General (and first President after 1963); and Dr Obafemi Awolowo the leader of opposition."]),
   ("The First Republic", ["A federation of three regions (North, East, West; the Mid-West created in 1963); a parliamentary system (the Prime Minister and cabinet); the Westminster model with the Governor-General representing the Queen. Regional politics were tense: the census dispute of 1962–63, the Western Region crisis (the Action Group's 1962 crisis), the Tiv riots, the 1964 federal election crisis and the 1965 Western election's 'operation wetie' violence."]),
   ("Fall of the Republic", ["The January 1966 coup (led by Nzeogwu and others) overthrew the government, killed the Prime Minister, and ended the First Republic. Causes of instability: regionalism, ethnicity, rigged elections, corruption and the struggle for power."]),
   ("Class evaluation", ["When did Nigeria become independent and a republic?", "Name the first Prime Minister and the first President.", "Give two causes of the crises of the First Republic.", "What event ended the First Republic?"])]),
 ("The Coups & Military Rule (1966–1999)",
  [("Introduction", ["Nigeria spent about 30 of its years since independence under military rule (1966–1979, 1983–1999). The coups and counter-coups, the civil war, the oil boom, and the return to democracy in 1999 define this period."]),
   ("The coups", ["January 1966 — the first coup (majors Nzeogwu and others); July 1966 — the counter-coup (Lt. Col. Yakubu Gowon emerged); and the civil war (1967–70). Gowon ruled until 1975 (the anniversary syndrome), then Murtala Mohammed (1975–76, killed in the Dimka coup); Olusegun Obasanjo (1976–79) handed over to Shagari (the Second Republic); the 1983 coup (Muhammadu Buhari); the 1985 coup (Ibrahim Babangida, who annulled the 1993 election — the June 12 crisis); the interim government of Ernest Shonekan (1993); and Sani Abacha (1993–1998); Abdulsalami Abubakar (1998–99) returned power to democracy on 29 May 1999."]),
   ("Achievements and failures", ["Achievements: the creation of states (from 4 regions to 36 states), the Federal Capital Territory (Abuja), the civil war victory and 'no victor, no vanquished', the Nigerianisation of the civil service, development projects (the oil era), and the eventual return to democracy. Failures: corruption, the annulment of June 12, human rights abuses, poor governance, and the stagnation of many institutions."]),
   ("The Second Republic (1979–1983)", ["The 1979 Constitution (the American presidential model) and Shehu Shagari's NPN government; the 'politics of money' and rigging; the collapse of the economy (the oil glut); and the 1983 coup under Buhari — the end of the Second Republic."]),
   ("Class evaluation", ["List three Nigerian coups and their leaders.", "Who annulled the June 12, 1993 election?", "How many states were created? Name the current number.", "State one achievement and one failure of military rule."])]),
 ("The Second Republic (1979-1983) & Return to Democracy",
  [("Introduction", ["The military handed power back to civilians in 1979, creating the Second Republic — a full replica of the American presidential system. It collapsed in 1983, and democracy returned only in 1999. This week studies the period."]),
   ("The 1979 Constitution", ["The constitution adopted the American presidential model: an executive president (elected separately, the head of state and government), a National Assembly (Senate and House of Representatives), an independent judiciary, separation of powers and checks and balances, a two-term limit, and the federal character principle — designed to distribute offices and calm ethnic tension."]),
   ("The 1979 and 1983 elections", ["The 1979 elections produced Alhaji Shehu Shagari (NPN) as president — after the famous interpretation of the '25% in two-thirds of the states' requirement by the Supreme Court; the NPN won the federal centre with its 'politics of ethnic arithmetic' (the NPN–NPN–NPN 'north–south balancing'). The 1983 elections were marred by rigging — the massive, open manipulation that destroyed the credibility of the republic."]),
   ("The fall of the republic", ["The economy collapsed (the oil boom ended — the 1982 world oil glut); salaries were not paid; corruption grew openly; the rigged 1983 elections alienated the people; and on 31 December 1983, General Muhammadu Buhari overthrew the government in a coup — the Third Republic never emerged; General Babangida's annulment of the June 12, 1993 election and the military rule of Abacha (1993–1998) followed, and democracy returned in May 1999 with President Olusegun Obasanjo."]),
   ("Class evaluation", ["What constitution created the Second Republic?", "State three features of the 1979 Constitution.", "Who won the 1979 presidential election?", "Why did the Second Republic collapse?", "When did democracy return to Nigeria?"])]),
]
